/* From Uiverse.io by mateusneves - Tags: button */
.__UIV_SCOPE__ button {
 position: relative;
 font-size: 14px;
 letter-spacing: 3px;
 height: 3em;
 padding: 0 3em;
 border: none;
 background-color: #c41b54;
 color: #fff;
 text-transform: uppercase;
 overflow: hidden;
 border-radius: 5px
}

.__UIV_SCOPE__ button::before {
 content: '';
 display: block;
 position: absolute;
 z-index: 0;
 bottom: 0;
 left: 0;
 height: 0px;
 width: 100%;
 background: rgb(196,27,84);
 background: linear-gradient(90deg, rgba(196,27,84,1) 20%, rgba(124,7,46,1) 100%);
 transition: 0.2s;
}

.__UIV_SCOPE__ button .label {
 position: relative;
}

.__UIV_SCOPE__ button .icon {
 display: flex;
 align-items: center;
 justify-content: center;
 height: 3em;
 width: 3em;
 position: absolute;
 top: 3em;
 right: 0;
 opacity: 0;
 transition: 0.4s;
}

.__UIV_SCOPE__ button:hover::before {
 height: 100%;
}

.__UIV_SCOPE__ button:hover .icon {
 top: 0;
 opacity: 1;
}
